CREATE UNIQUE INDEX `index_adjustment_org_id_uq` ON `index_adjustment` (`organization_id`,`id`);--> statement-breakpoint
CREATE UNIQUE INDEX `index_adjustment_agreement_date_uq` ON `index_adjustment` (`agreement_id`,`effective_date`);--> statement-breakpoint
CREATE TABLE `index_clause` (
	`agreement_id` text PRIMARY KEY NOT NULL,
	`organization_id` text NOT NULL,
	`share_percent` integer DEFAULT 100 NOT NULL,
	`base_month` text NOT NULL,
	`adjustment_month` integer DEFAULT 1 NOT NULL,
	`floor_at_base` integer DEFAULT true NOT NULL,
	`created_at` integer DEFAULT (cast(unixepoch('subsecond') * 1000 as integer)) NOT NULL,
	FOREIGN KEY (`organization_id`) REFERENCES `organization`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`organization_id`,`agreement_id`) REFERENCES `agreement`(`organization_id`,`id`) ON UPDATE no action ON DELETE cascade
);
